/* From Uiverse.io by mrhyddenn - Tags: button */
.__UIV_SCOPE__ button {
  background: #fff;
  border: none;
  padding: 10px 20px;
  display: inline-block;
  font-size: 15px;
  font-weight: 600;
  width: 120px;
  text-transform: uppercase;
  cursor: pointer;
  transform: skew(-21deg);
}

.__UIV_SCOPE__ span {
  display: inline-block;
  transform: skew(21deg);
}

.__UIV_SCOPE__ button::before {
  content: '';
  position: absolute;
  top: 0;
  bottom: 0;
  right: 100%;
  left: 0;
  background: rgb(20, 20, 20);
  opacity: 0;
  z-index: -1;
  transition: all 0.5s;
}

.__UIV_SCOPE__ button:hover {
  color: #fff;
}

.__UIV_SCOPE__ button:hover::before {
  left: 0;
  right: 0;
  opacity: 1;
}
